def is_samepatterns(colors, patterns):
    """
    Check if the sequence of colors follows the same pattern as the given patterns.

    Args:
        colors (list): List of colors to check.
        patterns (list): List of patterns to compare against.

    Returns:
        bool: True if the patterns match, False otherwise.
    """
    if len(colors) != len(patterns):
        return False

    for i in range(len(patterns)):
        for j in range(i + 1, len(patterns)):
            if patterns[i] == patterns[j]:
                if colors[i] != colors[j]:
                    return False
    return True
```

