def number_ctr(s):
    count = 0
    consecutive_digits = 0
    for char in s:
        if char.isdigit():
            consecutive_digits += 1
        else:
            if consecutive_digits > 0:
                count += 1
                consecutive_digits = 0
    # Add one more if the string ends with digits
    if consecutive_digits > 0:
        count += 1
    return count
